from src.nodes.base import BaseNode
from src.runtime.assets.acquisition import get_library_watcher
import json

class Hou_Mcp_Library_Watch(BaseNode):
    name = "hou_mcp_library_watch"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",      "string", widget_type="text", default="detect")
        self.add_input("watch_paths", "string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("events_json", "string")
        self.add_output("new_count",   "int")

    async def execute(self, inputs):
        action      = str(inputs.get("action",      "detect") or "detect").strip().lower()
        watch_paths = str(inputs.get("watch_paths", "")       or "")
        watcher = get_library_watcher()
        try:
            if action == "watch":
                paths = [p.strip() for p in watch_paths.split(";") if p.strip()]
                entries = watcher.watch(paths)
                self.log_info(f"Library watch: registered {len(entries)} path(s).")
                return {"events_json": json.dumps({"watched": [e.to_dict() for e in entries]}, sort_keys=True, default=str),
                        "new_count": 0, "exec_out": True}
            elif action == "snapshot":
                total = watcher.take_snapshot()
                self.log_info(f"Library watch snapshot: {total} file(s) recorded.")
                return {"events_json": json.dumps({"snapshot_files": total}, sort_keys=True),
                        "new_count": 0, "exec_out": True}
            elif action == "detect":
                events = watcher.detect_new_assets()
                self.log_info(f"Library watch detect: {len(events)} new asset(s) found.")
                return {"events_json": json.dumps([e.to_dict() for e in events], sort_keys=True, default=str),
                        "new_count": len(events), "exec_out": True}
            elif action == "stats":
                stats = watcher.get_statistics()
                return {"events_json": json.dumps(stats, sort_keys=True, default=str),
                        "new_count": 0, "exec_out": True}
            elif action == "recent":
                events = watcher.get_recent_events(limit=50)
                return {"events_json": json.dumps([e.to_dict() for e in events], sort_keys=True, default=str),
                        "new_count": len(events), "exec_out": True}
            else:
                self.log_error(f"Unknown action: {action!r}. Use: watch, snapshot, detect, stats, recent.")
                return {"events_json": "{}", "new_count": 0, "exec_out": True}
        except Exception as exc:
            self.log_error(f"Library watch failed: {exc}")
            return {"events_json": "{}", "new_count": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Library_Watch
